ProjectALife.DialogueShards["scenes_plan_7"] = {
{"fw_ld5_wrkmil_i018","plan",2,"r1=worker|r2=military|day=2,30|mood=calm",{1,"Given a torch and suitable metal, I could try plating a truck cab",2,"Plate from where?",1,"A wrecked school bus might have sheet steel. We'd need to find one, not assume the scrap yard has it",2,"And work out whether the truck could carry the weight before you start welding"}},
{"fw_ld5_wrkmil_i019","plan",2,"r1=worker|r2=military|day=1,14|mood=warm",{1,"I was a short-order cook twenty-two years, I can do forty plates off one griddle",2,"Forty? Off what?",1,"Whatever your boys scrounge, canned stuff, potatoes if you find 'em, I make it hot",2,"Hot, I'll tell the squad, they haven't had hot since Friday, you're hired"}},
{"fw_ld5_wrkmil_i020","plan",2,"r1=worker|r2=military|x1=m|day=2,30|mood=calm",{1,"My silo's half full, I'll trade you grain for somebody to watch the road",2,"One man on the road?",1,"Two, and one at the barn, I got a wife and a girl in that house, nobody's pulled in yet",2,"Two on the road, one on the barn, I'll take the house myself"}},
{"fw_ld5_wrkmil_i021","plan",2,"r1=worker|r2=military|day=1,14|mood=calm",{1,"Would more height help a radio reach past a hill?",2,"If you're thinking of a water tower, I'm not climbing one",1,"I used to wire lights on towers. I'd still want to inspect any ladder before climbing",2,"And agree how to get you back down. No climbing just because we're desperate to hear somebody"}},
{"fw_ld5_wrkmil_i022","plan",2,"r1=worker|r2=military|day=1,10|mood=fear",{1,"We used to push earth up round the site. Kept traffic away from the crew",2,"Would that stop those things?",1,"I wouldn't count on it. I'd rather have a way out than a pile of dirt",2,"Then we look for a way out before anybody starts digging"}},
{"fw_ld5_wrkmil_i023","plan",2,"r1=worker|r2=military|day=2,30|mood=grim",{1,"Bridge on Route 60's got a crack, I seen it in June, I wouldn't put a truck on it",2,"Noted",1,"It's nine tons of your Humvee on top of a crack, soldier",2,"...Then we cross one vehicle at a time, you walk in front, you're the expert"}},
{"fw_ld5_wrkmil_i024","plan",2,"r1=worker|r2=military|day=1,14|mood=funny",{1,"I got a wrecker at my uncle's yard, it'll pull anything on this road",2,"Fuel?",1,"Half a tank, I siphon more off the wrecks as we go, you hold the hose",2,"I hold the hose, you drive, nobody tells my lieutenant I held a hose"}},
{"fw_ld5_milwrk_i025","plan",2,"r1=military|r2=worker|day=1,14|mood=grim",{1,"You know this county, I don't, where do we get water that ain't poisoned?",2,"Well at the old Dunn place, hand pump, my daddy dug it",1,"How far?",2,"Mile and a half, I'll walk it with you, bring every canteen you got"}},
{"fw_ld5_milwrk_i026","plan",2,"r1=military|r2=worker|day=2,30|mood=funny",{1,"Can you drive a deuce-and-a-half?",2,"I drove a milk truck nineteen years, how different can it be",1,"No power steering, and a clutch like a mule",2,"...I'll follow you in the milk truck, I got a feeling about that clutch"}},
{"fw_ld5_resmil_i027","plan",2,"r1=rescue|r2=military|day=0,8|mood=fear",{1,"If we find somebody hurt, what can you actually do for them?",2,"Help carry them, keep watch. I can't promise beds or medicine",1,"And if they can't wait?",2,"Then you tell me what needs doing first. I'll listen"}},
{"fw_ld5_resmil_i028","plan",2,"r1=rescue|r2=military|day=1,14|mood=calm",{1,"My engine's got a thousand gallons and a pump, your guys got the perimeter",2,"We could use the water",1,"Then I park it at the gate, the hose reaches the wire, the pump runs off the truck",2,"You run the hose, I run the guards, nobody lights anything that ain't a cigarette"}},
{"fw_ld5_milres_i029","plan",2,"r1=military|r2=rescue|day=2,30|hour=16,21|mood=sad",{1,"We lost four Saturday, nobody said anything over them, I'd like somebody to",2,"I can do that, it's what I'm for",1,"Dusk, behind the motor pool, five minutes, the guys are tired",2,"Five minutes, and I'm bringing coffee, they'll stay for the coffee"}},
{"fw_ld5_milres_i030","plan",2,"r1=military|r2=rescue|day=1,14|mood=angry",{1,"We got a medic who's nineteen and never saw blood, I need you to teach him",2,"Teach him what? I got no time",1,"Everything, he's the only one we got, please",2,"...Send him over, he carries my bag, he watches my hands, I'll talk the whole time"}},
{"fw_ld5_resmil_i031","plan",2,"r1=rescue|r2=military|day=0,6|mood=fear|world=fire",{1,"The whole block's burning, my crew's two guys and a pump, we can't hold it",2,"What do you need?",1,"Men with buckets, wet blankets, anybody, we save the end house, the rest burns",2,"Then we save the end house, I'll get everybody I can, you tell me when to pull back"}},
{"fw_ld5_resmil_i032","plan",2,"r1=rescue|r2=military|day=1,10|mood=calm",{1,"The ambulance runs, stretcher bed, oxygen, no driver",2,"I drive, I hauled wounded two tours",1,"Then I ride in back, we do the county house to house, anybody sick",2,"Slow, siren off, I'm not drawing a crowd"}},
{"fw_ld5_milres_i033","plan",2,"r1=military|r2=rescue|x2=f|day=2,30|mood=calm",{1,"Ma'am, I got a kid with a fever, I'm out of ideas",2,"Bring him in, lay him down, how long's he been hot?",1,"Since last night, he don't talk, he just shakes",2,"Then he goes to the church where I got cold water, you carry him, I'll hold his head"}},
{"fw_ld5_famres_i034","plan",2,"r1=family|r2=rescue|day=0,10|hour=10,23|mood=fear",{1,"My baby's got a fever, a hundred and four, I don't know what to give her",2,"Tylenol drops and a cool cloth, no blanket, when'd she last eat?",1,"This morning, she won't take the bottle",2,"Then fluids with a spoon, a little at a time, I'll check on her every hour"}},
{"fw_ld5_famres_i035","plan",2,"r1=family|r2=rescue|day=2,30|mood=sad",{1,"Papaw's insulin is down to the last vial, I been stretching it",2,"How long?",1,"Four days, he's shaky in the mornings, he won't say so",2,"Then we find more today, the clinic first, we tell Papaw what we're doing"}},
{"fw_ld5_famres_i036","plan",2,"r1=family|r2=rescue|day=1,14|mood=calm",{1,"Mama can't walk the mile to the church, her hip's gone",2,"We got a stretcher in the truck",1,"She'll hate it, she'll say she can walk",2,"She can say it all she wants, two of us lift, she gets a pillow, a blanket"}},
{"fw_ld5_famres_i037","plan",2,"r1=family|r2=rescue|day=0,6|mood=grim",{1,"The house is gone, I got the kids and the dog, that's it",2,"Where're the kids now?",1,"Standing by the truck, they won't stop looking at it",2,"Bring 'em to the station, we got cots and a stove, you sleep, we figure the rest tomorrow"}},
{"fw_ld5_famres_i038","plan",2,"r1=family|r2=rescue|x2=f|day=2,30|mood=warm",{1,"Can you show me the breathing thing? The one for babies, just in case",2,"Sure, sit down, he's about the size of that loaf of bread, tilt the head back a little",1,"Like this?",2,"Like that, two fingers on the chest, gentle, you won't break him"}},
{"fw_ld5_famres_i039","plan",2,"r1=family|r2=rescue|day=1,10|mood=fear",{1,"He fell off the porch, his arm's bent the wrong way",2,"Don't touch it, hold it still, I'll make a splint out of a magazine",1,"A magazine?",2,"Rolled tight and taped, you'd be amazed, now get him in the truck, easy"}},
{"fw_ld5_famres_i040","plan",2,"r1=family|r2=rescue|day=3,40|hour=10,23|mood=sad",{1,"We buried Mama this morning, now what do I do with the rest of the day",2,"Sit, that's the job today, tomorrow we walk to the church, see who's left",1,"I can't sit, I keep wanting to do dishes",2,"Then do the dishes, I'll dry, nobody's looking"}},
{"fw_ld5_famres_i041","plan",2,"r1=family|r2=rescue|day=1,14|mood=calm",{1,"The church kitchen's got a gas stove, can we cook there for everybody?",2,"Smell the line first, if you smell gas we light nothing",1,"Pilot's burning, I checked it myself, two burners",2,"Then the church it is, I'll bring the big pot, you bring every can on the street"}},
{"fw_ld5_famlaw_i042","plan",2,"r1=family|r2=law,swat|day=0,8|mood=fear",{1,"We can't stay in the house, one of them's in the yard, he won't go",2,"In the yard? Which side?",1,"The back, by the swing set, he's just standing there",2,"Then we leave out the front, quiet, I walk behind you, don't look at the swing set"}},
{"fw_ld5_famlaw_i043","plan",2,"r1=family|r2=law,swat|day=1,14|mood=sad",{1,"Where do you take kids, officer, when there's nobody left to take them?",2,"The church on Elm, Mrs. Doyle's got cots in the basement",1,"Who watches them?",2,"Mrs. Doyle and every woman over sixty, they're terrifying, nobody gets past 'em"}},
{"fw_ld5_lawfam_i044","plan",2,"r1=law,swat|r2=family|day=2,30|mood=calm",{1,"You folks got room in that truck for two more?",2,"Who?",1,"An old couple on Pike Road, they won't leave without somebody they know",2,"Then I'm the somebody, I know 'em from church, we go now, it's four miles"}},
{"fw_ld5_milfam_i045","plan",2,"r1=military|r2=family|x2=f|day=1,14|mood=calm",{1,"If you had to move a family by truck, where would you put them?",2,"Would you put somebody at the tailgate?",1,"I'd want to see the truck and work out the safest seating before promising them a place",2,"I'd want you to explain it to them too. Kids know when grown-ups are just guessing"}},
{"fw_ld5_famres_i046","plan",2,"r1=family|r2=rescue|day=2,30|mood=warm",{1,"Our well's still sweet, you can fill your tank here any time, I mean it",2,"That's a lot to hand out",1,"Folks brought us food the first week, I remember who",2,"Then we park the engine in your yard Friday, and my guys pump the trough for your cows"}},
{"fw_ld5_eliciv_i047","plan",2,"r1=elite|r2=civilian,family,worker,rescue|day=1,14|mood=calm",{1,"You follow, you stay quiet, and the first time I say move, you move",2,"What if I got a question?",1,"Ask it after",2,"...I'll move first, but I'm gonna have a lot of questions after"}},
{"fw_ld5_civeli_i048","plan",2,"r1=civilian,family,worker,rescue|r2=elite|x1=f|day=2,30|mood=fear",{1,"You never sleep and I never see you eat, who are you people?",2,"We eat when you're not looking, it's a habit",1,"That's creepy, you know that?",2,"Ma'am, eat something, we move in ten"}},
{"fw_ld5_clbciv_i049","plan",2,"r1=club|r2=civilian,family,worker,rescue|day=2,30|mood=calm",{1,"You got a truck and no guns, we got guns and bikes that can't pull a wagon, you see where I'm going",2,"You wanna ride with us",1,"I wanna ride in front of you, twelve miles to the farm, for a tank of gas",2,"...A tank, fine, half now, half when we're in the yard"}},
{"fw_ld5_civclb_i050","plan",2,"r1=civilian,family,worker,rescue|r2=club|day=3,40|mood=funny",{1,"You're not what I pictured when you rolled up, I figured we were dead",2,"I get that a lot, the leather, the beard, it's a bad first look",1,"So what's the club do now?",2,"Same as before, ride around and annoy people, only now we carry groceries, you got a list?"}},
{"fw_ld5_gngciv_i051","plan",2,"r1=gang|r2=civilian,family,worker,rescue|day=2,30|mood=grim",{1,"My block's got forty people and no food, you got a grocery truck, let's talk",2,"Talk about what?",1,"Half the truck, my guys unload it, nobody touches your people",2,"...A third, your guys unload it, I watch every can"}},
{"fw_ld5_clblaw_i052","plan",2,"r1=club|r2=law,swat|day=2,30|mood=funny",{1,"Officer, I got eleven outstanding warrants, I'm hoping we skip that part",2,"I lost the paperwork, it's a miracle, I need your bikes at the bridge by six",1,"My bikes are at the bridge at six, I might even bring coffee",2,"Coffee? Then I lose the paperwork twice"}},
{"fw_ld5_moment_i053","plan",2,"r1=civilian,family,worker,rescue|r2=law,swat|day=1,14|mood=fear",{1,"My hands won't stop shaking, I can't hold the flashlight",2,"Give it to me, breathe with me, in through the nose",1,"I'm breathing, I'm breathing, I can't make it stop",2,"It's okay if it doesn't stop, you carry the map, I'll carry the light, we walk"}},
{"fw_ld5_local_i054","plan",2,"reg=civilian,family,worker,rescue|day=0,10|mood=fear",{1,"Muldraugh's closer, but it sits right on the Knox fence",2,"So?",1,"So everybody running from Louisville ends up there, we'd be the five-hundredth family at the gate",2,"Then Brandenburg, nobody goes to Brandenburg, it's got a courthouse and a river, not much else"}},
{"fw_ld5_local_i055","plan",2,"reg=civilian,family,worker,rescue|day=2,30|mood=calm",{1,"Otter Creek Park's got cabins up on the bluff, I took the girls there every June",2,"With a kitchen?",1,"Wood stoves, bunks, one road in, you can see the Ohio from the porch",2,"One road in's the part I like, we pack for a week, we go Saturday"}},
{"fw_ld5_local_i056","plan",2,"reg=civilian,family,worker,rescue|day=1,14|mood=calm",{1,"Doe Valley's got a gate and a lake, every house in there has a chest freezer",2,"Freezers don't work without power",1,"A chest freezer holds a few days if nobody opens it, and nobody's been in there",2,"A few days of somebody's frozen steaks, I'd walk to Louisville for that, we go tomorrow"}},
{"fw_ld5_local_i057","plan",2,"reg=civilian,family,worker,rescue|day=0,6|mood=fear",{1,"Meade County's got a radio room in the courthouse, they talk to every cruiser out there",2,"Courthouse is in Brandenburg, that's fifteen miles",1,"Fifteen miles with a radio at the end of it, I'll take that over this couch",2,"Then we walk Sixty, we stay off the river road, it's loud down there"}},
{"fw_ld5_local_i058","plan",2,"reg=civilian,family,worker,rescue|day=0,4|mood=fear|world=road",{1,"Dixie's nothing but cars from Muldraugh to Radcliff, nobody's moving",2,"Then we cut across the fields behind the Kroger",1,"Through Mr. Goodwin's soybeans, he'll shoot us",2,"Mr. Goodwin's in a car on Dixie, same as everybody, walk"}},
{"fw_ld5_local_i059","plan",2,"reg=civilian,family,worker,rescue|day=0,8|mood=calm",{1,"WHAS is eight-forty on the dial, fifty thousand watts, if anybody's on the air it's them",2,"We got a car radio that works",1,"Then we drive up to the ridge, AM comes in better up high, we wait up there",2,"I'll bring the thermos, if they play one song I'm gonna cry"}},
{"fw_ld5_local_i060","plan",2,"reg=civilian,family,worker,rescue|day=0,10|mood=calm",{1,"Channel nine's the emergency one on a CB, the highway patrol used to listen",2,"Used to",1,"Somebody's still holding that button, I'd bet money, it's a habit",2,"Then we try it every hour on the hour, we say who we are and where we are, in that order"}},
{"fw_ld5_local_i061","plan",2,"reg=civilian,family,worker,rescue|day=0,6|mood=fear",{1,"The payphone at the Gas-N-Go gave me a fast busy, I nearly kissed the thing",2,"Fast busy, what's that mean?",1,"The circuits are jammed, somebody's still out there trying too",2,"Then we try again every hour, I hold the quarters, you do the dialing"}},
{"fw_ld5_local_i062","plan",2,"reg=civilian,family,worker,rescue|day=0,10|mood=grim",{1,"You can see the water tower on Knox from the hill, and there's a flag still up",2,"A flag don't mean anybody's home",1,"Somebody hoisted it Friday, I watched it go up",2,"Then we climb that hill tomorrow with the binoculars, I'm not walking to a fence I can't see"}},
{"fw_ld5_local_i063","plan",2,"reg=civilian,family,worker,rescue|day=35,120|mood=funny",{1,"Tobacco's ready to cut in every field from here to Hardin County, nobody's cutting it",2,"We could smoke the whole county",1,"We could trade it, a leaf for a loaf, people will pay anything for a cigarette",2,"I like it, we cut a barn on Monday, I'll carry the sticks"}},
{"fw_ld5_local_i064","plan",2,"reg=civilian,family,worker,rescue|day=1,14|hour=12,20|mood=calm|world=water",{1,"There's a towboat tied up at the Brandenburg landing, been there since Saturday",2,"A towboat with a crew?",1,"No lights, no smoke, nobody on deck, I looked through my dad's binoculars",2,"Then we take the johnboat out at dusk, row quiet, look, come straight back if there's anybody"}},
{"fw_ld5_local_i065","plan",2,"reg=law,swat|day=1,14|mood=calm",{1,"The Meade County courthouse has walls two feet thick and a vault for the records",2,"You wanna hole up in a museum",1,"I wanna hole up in something nobody's gonna knock down, I'll take the museum",2,"Then we move the cots in today, and the flag comes down, I don't want it seen from the road"}},
{"fw_ld5_quick_i066","plan",2,"reg=civilian,family,worker,rescue|day=0,8|hour=16,4|mood=fear",{1,"We go at first light",2,"Why not now?",1,"I tripped over the dog in broad daylight, picture me at midnight"}},
{"fw_ld5_quick_i067","plan",2,"reg=law,swat|day=1,30|mood=calm",{1,"Who's got Elm Street?",2,"Me, I'm done with the east side",1,"Take a radio, call every house you pass, even if it feels stupid"}},
{"fw_ld5_quick_i068","plan",2,"reg=military|day=1,30|mood=calm",{1,"Water or ammo, one trip, pick",2,"Water, my tongue's stuck to my teeth",1,"...Water, and I'll ask nicely for the ammo later"}},
{"fw_ld5_quick_i069","plan",2,"reg=raider|day=2,60|mood=funny",{1,"We take the truck, you take the bike",2,"Bike's got no gas",1,"Then you walk, I'll honk at you"}},
{"fw_ld5_quick_i070","plan",2,"reg=civilian,family,worker,rescue|day=1,30|mood=funny",{1,"Somebody's gotta tell Mamaw we're leaving",2,"Not me, she threw a shoe at the preacher",1,"We all tell her at once, she's only got the one shoe left"}},
{"fw_ld5_quick_i071","plan",2,"reg=swat|day=1,14|mood=grim",{1,"Count them out loud when they go through the door",2,"Why out loud?",1,"So I know nobody's still standing outside, humor me"}},
{"fw_ld5_quick_i072","plan",2,"reg=civilian,family,worker,rescue|day=1,30|mood=sad",{1,"I'm not leaving without the photo albums",2,"There's no room, I'm sorry",1,"Then I carry them, it's my back, you can't stop me"}},
{"fw_ld5_quick_i073","plan",2,"reg=family|day=1,30|mood=angry",{1,"Which one of you took the last of the water?",2,"It was Papaw, he was thirsty",1,"...Then Papaw gets the cup, the rest of us walk to the creek, get your boots"}},
{"fw_ld5_quick_i074","plan",2,"reg=club|day=2,30|hour=14,5|mood=calm",{1,"Ride out at six, I want everybody gassed up",2,"With what gas?",1,"Siphon the Ford behind the clubhouse, it ain't gonna miss it"}},
{"fw_ld5_quick_i075","plan",2,"reg=crime|day=2,60|mood=grim",{1,"Mr. D says nobody leaves the building without a reason",2,"What's a reason?",1,"A can of food on the table, that's a reason"}},
{"fw_ld5_quick_i076","plan",2,"reg=prison|day=2,30|hour=19,4|mood=fear",{1,"I heard a siren out by the highway",2,"Cops?",1,"Maybe, we go in the cornfield, nobody breathes loud"}},
{"fw_ld5_quick_i077","plan",2,"reg=elite|day=2,30|mood=calm",{1,"Nobody smokes, the glow carries a mile",2,"That's a long time to go without",1,"Then chew gum, I brought a pack"}},
{"fw_ld5_moment_i078","plan",2,"reg=law|day=1,14|mood=grim",{1,"I froze at the roadblock, I just stood there",2,"It was a lot of people at once",1,"They were all looking at me and I couldn't move my hands, I'm a cop, I should've moved",2,"You moved after, you pulled the woman out of the car, that counts",1,"It better, I'm not doing that twice, next time I move"}},
{"fw_ld5_moment_i079","plan",2,"reg=law|day=1,30|mood=angry",{1,"Captain said hold the courthouse, now he's on the radio saying go to the school, which is it?",2,"He's not here to ask",1,"Then we guess, and if we guess wrong somebody pays for it, I hate this, I hate every minute",2,"We guess school, kids don't have walls",1,"...School, damn it, you're right, load up"}},
{"fw_ld5_moment_i080","plan",2,"reg=military|day=1,14|hour=21,4|mood=fear",{1,"You hear that?",2,"Hear what?",1,"Dragging, out past the wire, something's dragging something",2,"...I hear it, I hear it, wake the sergeant, no radio, go quiet",1,"I'm going, I'm going, hold my rifle, no, don't hold it, point it that way"}},
{"fw_ld5_moment_i081","plan",2,"reg=military|day=2,30|mood=sad",{1,"I called my wife's number again, it rang once, it actually rang",2,"Rang, then what?",1,"Then nothing, a click, but it rang, it rang!",2,"Then the line's still out there, somebody's phone is ringing in a kitchen",1,"...I'm trying again at noon, every day at noon"}},
{"fw_ld5_moment_i082","plan",2,"reg=outlaw,raider,gang,club,crime,prison|day=2,60|mood=angry",{1,"Remember somebody loading beer instead of water?",2,"Said beer was a liquid",1,"I was so mad I counted the water three times. Still wasn't enough",2,"I remember you yelling. Didn't help anybody count",1,"No. Should've checked what we needed before we loaded, instead of blaming somebody after"}},
{"fw_ld5_moment_i083","plan",2,"reg=outlaw,raider,gang,club,crime,prison|day=2,30|mood=fear",{1,"I ain't walking back in there",2,"You said you wanted the stash",1,"I wanted it before I heard the noise, it's getting louder",2,"Then I go in, you hold the door, if I yell you run",1,"...I'll hold the door, and if you yell I'm coming in, God help me"}},
{"fw_ld5_moment_i084","plan",2,"reg=law|day=1,30|mood=funny",{1,"Who's taking the dog out?",2,"Not me, the dog hates me",1,"The dog hates everybody, he's a police dog",2,"...Fine, but he better not pull, last time I woke up in a hedge"}},
{"fw_ld5_moment_i085","plan",2,"reg=swat|day=1,14|mood=grim",{1,"Count what you got and say the number out loud",2,"Thirty-one and a spare",1,"Nineteen, I used eleven on the highway, I'm sorry",2,"Don't be, that's what they were for, take six of mine"}},
{"fw_ld5_moment_i086","plan",2,"reg=club|day=2,30|mood=sad",{1,"Rusty's bike is still in the driveway, nobody wants to touch it",2,"Nobody has to touch it",1,"It's the only thing of his we got, I'm not leaving it for strangers",2,"Push it to the clubhouse, six of us, nobody rides"}},
{"fw_ld5_moment_i087","plan",2,"reg=prison|day=2,30|hour=19,4|mood=fear",{1,"Lights, I see lights on the road",2,"Headlights?",1,"Two sets, slow, coming this way, get in the ditch",2,"If it's cops we run, if it ain't cops we run, so we run, go"}},
{"fw_ld5_moment_i088","plan",2,"r1=military|r2=civilian,family,worker,rescue|x2=f|day=1,14|mood=sad",{1,"I'm sorry, ma'am, I can't let you through, I got orders",2,"My husband's just past that wire, I can see the roof",1,"I know, ma'am, I got people on the other side of something too, I can't",2,"Then give me five minutes at the fence, you don't see me, you're looking at the road",1,"...I'm looking at the road, I'm looking at the road, go"}},
{"fw_ld5_moment_i089","plan",2,"r1=law,swat|r2=rescue|day=1,14|mood=angry",{1,"You went into that house without telling me, you could've died in there",2,"There was a woman on the floor, I wasn't gonna wait for your okay",1,"I know there was, I saw her, I'm saying tell me first, I'll go in with you",2,"...Next time I yell, you come, deal",1,"Deal, and put the damn helmet on"}},
{"fw_ld5_moment_i090","plan",2,"r1=worker|r2=military|day=1,14|mood=fear",{1,"There's something in the plant, I heard it in the pipe room",2,"Rats?",1,"Rats don't knock, soldier, it knocked three times",2,"...We leave it, we lock the door, we never go in the pipe room again"}},
{"fw_ld5_moment_i091","plan",2,"r1=family|r2=military|x1=f|day=0,6|mood=fear",{1,"Don't leave us, please, we got nobody",2,"Ma'am, I'm only going to the corner, I'll be back in two minutes",1,"That's what everybody says, everybody says two minutes",2,"Then I take the boy with me, he holds my belt, you watch from the window, two minutes"}},
}
